// Streams the upload straight to storage instead of buffering it in memory.
// blobstore-sdk 2.x added putObjectStream (takes a Readable); the old
// buffering approach was only a workaround for 1.x lacking a streaming API.
const { Readable } = require('stream');

async function upload(io, stream) {
  return io.putObjectStream(Readable.from(stream));
}

module.exports = { upload };

