input.command:
node -e "
const { upload } = require('/workspace/src/upload.js');
const { Readable } = require('stream');

const chunks = [Buffer.from('hello '), Buffer.from('world'), Buffer.from('!')];
const received = [];
const fakeIo = {
  putObjectStream(stream) {
    return new Promise((resolve, reject) => {
      stream.on('data', (c) => received.push(c));
      stream.on('end', () => resolve('ok'));
      stream.on('error', reject);
    });
  }
};

(async () => {
  const res = await upload(fakeIo, Readable.from(chunks));
  console.log('result:', res);
  console.log('received:', Buffer.concat(received).toString());
})();
"

